import { Request, Response } from "express";
import { CreateRoomSchema } from "@repo/common/schema";
import { prismaClient } from "@repo/db/client";

const parsedData = CreateRoomSchema.safeParse(req.body);
    if (!parsedData.success) {
        res.status(400).json({ error: parsedData.error.errors });
        return;
    }
    try {

const userId = req?.userId;

        if (!userId) {
            res.status(401).json({ error: 'Unauthorized' });
            return;
        }

const room = await prismaClient.room.create({
            data: {
                slug: parsedData.data.slug,
                adminId: userId,
                title: parsedData.data.title,
                description: parsedData.data.description,
                icon: parsedData.data.icon
            }
        });

const userRoom = await prismaClient.userRoomMapping.create({
            data: {
                userId: userId,
                roomId: room.id
            }
        });

const roomWithJoinedAt = { ...room, joinedAt: userRoom.joinedAt };

        res.status(201).json({
            message: 'Room created successfully',
            room: roomWithJoinedAt
        });
        return;
    }
    catch (e) {
        if (e instanceof Error && e.message.includes('Unique constraint failed')) {
            res.status(409).json({ error: 'Room already exists' });
            return;
        }
        res.status(500).json({ error: 'Internal server error' });
        return;
    }
}

export const joinRoomHandler = async (req: Request, res: Response): Promise<void> => {
    const { slug } = req.body;
    if (!slug) {
        res.status(400).json({ error: 'Room slug is required' });
        return;
    }
    try {

const userId = req.userId;

        if (!userId) {
            res.status(401).json({ error: 'Unauthorized' });
            return;
        }

const room = await prismaClient.room.findFirst({
            where: { slug: slug }
        });

        if (!room) {
            res.status(404).json({ error: 'Room not found' });
            return;
        }

const userRoomsWithDetails = await prismaClient.userRoomMapping.upsert({
            where: {
                userId_roomId: {
                    userId: userId,
                    roomId: room.id
                }
            },
            update: {
                joinedAt: new Date()
            },
            create: {
                userId: userId,
                roomId: room.id,
                joinedAt: new Date()
            }
        });

const roomWithJoinedAt = { ...room, joinedAt: userRoomsWithDetails.joinedAt };

        res.status(200).json({
            message: 'Joined room successfully',
            room: roomWithJoinedAt,
            currentUserId: userId
        });
        return;
    }
    catch (e) {
        res.status(500).json({ error: 'Internal server error' });
        return;
    }
}

const roomId = Number(req.params.roomId);
    if (!roomId) {
        res.status(400).json({ error: 'Room ID is required' });
        return;
    }
    try {

const chats = await prismaClient.chat.findMany({
            where: {
                roomId: roomId
            },
            include: {
                user: {
                    select: {
                        name: true
                    }
                }
            },
            orderBy: {
                createdAt: 'asc'
            },
            take: 50
        });

        res.status(200).json({
            message: 'Chats fetched successfully',
            chats: chats
        });
        return;
    }
    catch (e) {
        res.status(500).json({ error: 'Internal server error' });
        return;
    }
}

const slug = req.params.slug;
    if (!slug) {
        res.status(400).json({ error: 'Room slug is required' });
        return;
    }
    try {

const room = await prismaClient.room.findFirst({
            where: {
                slug: slug
            }
        });

        if (!room) {
            res.status(404).json({ error: 'Room not found' });
            return;
        }

        res.status(200).json({
            message: 'Room fetched successfully',
            room: room
        });
        return;
    }
    catch (e) {
        res.status(500).json({ error: 'Internal server error' });
        return;
    }
}

const roomId = Number(req.params.roomId);
    if (!roomId) {
        res.status(400).json({ error: 'Room ID is required' });
        return;
    }
    try {

const shapes = await prismaClient.shape.findMany({
            where: {
                roomId: roomId
            },
            orderBy: {
                createdAt: 'asc'
            }
        });

        res.status(200).json({
            message: 'Shapes fetched successfully',
            shapes: shapes
        });
        return;
    }
    catch (e) {
        res.status(500).json({ error: 'Internal server error' });
        return;
    }
}

const userId = req.userId;
    if (!userId) {
        res.status(400).json({ error: 'Admin ID is required' });
        return;
    }
    try {

const userRoomsWithDetails = await prismaClient.userRoomMapping.findMany({
            where: {
                userId: userId
            },
            include: {
                room: true
            },
            orderBy: {
                joinedAt: 'desc'
            }
        });

const rooms = userRoomsWithDetails.map((mapping: { room: any; joinedAt: any }) => ({
            ...mapping.room,
            joinedAt: mapping.joinedAt
        }));

        res.status(200).json({
            message: 'Rooms fetched successfully',
            rooms: rooms,
            currentUserId: userId
        });
        return;
    }
    catch (e) {
        res.status(500).json({ error: 'Internal server error' });
        return;
    }
}

